changeSet.sql:
ALTER TABLE clinlims.validation_policy ADD CONSTRAINT ck_validation_policy_trigger
  CHECK (review_trigger IN ('ALL', 'NEEDS_REVIEW', 'NONE'));
ALTER TABLE clinlims.validation_policy ADD CONSTRAINT ck_validation_policy_levels
  CHECK (review_levels BETWEEN 0 AND 5 AND ((review_trigger = 'NONE') = (review_levels = 0)));
CREATE UNIQUE INDEX uq_validation_policy_lab_default ON clinlims.validation_policy ((1)) WHERE test_section_id IS NULL;
CREATE UNIQUE INDEX uq_validation_policy_test_section ON clinlims.validation_policy (test_section_id) WHERE test_section_id IS NOT NULL;
